function validate([maze, entrance]) {
  if (!Array.isArray(maze) || maze.length < 1 || maze.length > 100) return 'maze needs 1 to 100 rows.';
  const cols = Array.isArray(maze[0]) ? maze[0].length : 0;
  if (cols < 1 || cols > 100) return 'Each row needs 1 to 100 cells.';
  for (const line of maze) {
    if (!Array.isArray(line) || line.length !== cols) return 'Every row must have the same length.';
    if (line.some(cell => cell !== '.' && cell !== '+')) return "Each cell must be '.' or '+'.";
  }
  if (!Array.isArray(entrance) || entrance.length !== 2) return 'entrance must be [row, col].';
  const [r, c] = entrance;
  if (!Number.isInteger(r) || !Number.isInteger(c) || r < 0 || r >= maze.length || c < 0 || c >= cols) return 'entrance must lie inside the maze.';
  if (maze[r][c] !== '.') return 'The entrance must be an open cell.';
  return null;
}

