function nearestExit(maze, entrance) {
  // Relax distances over and over (Bellman-Ford style) until nothing improves, then scan the border.
  const rows = maze.length;
  const cols = maze[0].length;
  const dist = maze.map(line => line.map(() => Infinity));
  dist[entrance[0]][entrance[1]] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        if (maze[r][c] !== '.') continue;
        for (const [nr, nc] of [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]]) {
          if (nr < 0 || nc < 0 || nr >= rows || nc >= cols || maze[nr][nc] !== '.') continue;
          if (dist[nr][nc] + 1 < dist[r][c]) {
            dist[r][c] = dist[nr][nc] + 1;
            changed = true;
          }
        }
      }
    }
  }
  let best = Infinity;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const onEdge = r === 0 || c === 0 || r === rows - 1 || c === cols - 1;
      const isEntrance = r === entrance[0] && c === entrance[1];
      if (maze[r][c] === '.' && onEdge && !isEntrance) best = Math.min(best, dist[r][c]);
    }
  }
  return best === Infinity ? -1 : best;
}

