function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const randomMaze = (rows, cols, wallChance, closedBorder) => {
    const maze = [];
    for (let r = 0; r < rows; r++) {
      const line = [];
      for (let c = 0; c < cols; c++) {
        const edge = r === 0 || c === 0 || r === rows - 1 || c === cols - 1;
        line.push((closedBorder && edge) || rand() < wallChance ? '+' : '.');
      }
      maze.push(line);
    }
    return maze;
  };
  if (size !== 'large') {
    const rows = int(1, 6);
    const cols = int(1, 6);
    const maze = randomMaze(rows, cols, [0.15, 0.35, 0.55][int(0, 2)], false);
    const entrance = [int(0, rows - 1), int(0, cols - 1)];
    maze[entrance[0]][entrance[1]] = '.';
    return [maze, entrance];
  }
  const shape = int(0, 2);
  if (shape === 1) {
    // A winding corridor: open rows joined by single gaps that alternate sides, with one exit at the far end.
    const rows = int(80, 100);
    const cols = int(80, 100);
    const maze = Array.from({ length: rows }, () => new Array(cols).fill('+'));
    let lastRow = 1;
    let goingRight = true;
    for (let r = 1; r <= rows - 2; r += 2) {
      for (let c = 1; c <= cols - 2; c++) maze[r][c] = '.';
      if (r > 1) maze[r - 1][goingRight ? 1 : cols - 2] = '.';
      lastRow = r;
      goingRight = !goingRight;
    }
    // goingRight was flipped after the last corridor, so the walk along it ended on the opposite side.
    maze[lastRow][goingRight ? 0 : cols - 1] = '.';
    return [maze, [1, 1]];
  }
  const rows = int(60, 100);
  const cols = int(60, 100);
  const closed = shape === 2;
  const maze = randomMaze(rows, cols, 0.2 + rand() * 0.25, closed);
  if (closed) {
    // Open only a couple of exits on the walled border; it may be unreachable.
    const exits = int(0, 2);
    for (let e = 0; e < exits; e++) {
      if (rand() < 0.5) maze[rand() < 0.5 ? 0 : rows - 1][int(1, cols - 2)] = '.';
      else maze[int(1, rows - 2)][rand() < 0.5 ? 0 : cols - 1] = '.';
    }
  }
  const entrance = [int(1, rows - 2), int(1, cols - 2)];
  maze[entrance[0]][entrance[1]] = '.';
  return [maze, entrance];
}
